<?php
declare(strict_types=1);
require_once __DIR__.'/auth.php'; require_login(); $pdo=db();
if(!table_exists($pdo,'documents')) redirect('upgrade_phase3.php');
$msg=flash('success');$error=null;
$storage=__DIR__.'/uploads/documents';if(!is_dir($storage))mkdir($storage,0755,true);
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$client=post_int('client_id');if($client&&isset($_FILES['document'])&&$_FILES['document']['error']===UPLOAD_ERR_OK){try{$f=$_FILES['document'];if($f['size']>10*1024*1024)throw new RuntimeException('Maximum file size is 10 MB.');$fi=new finfo(FILEINFO_MIME_TYPE);$mime=$fi->file($f['tmp_name']);$allowed=['application/pdf','image/jpeg','image/png'];if(!in_array($mime,$allowed,true))throw new RuntimeException('Only PDF, JPG and PNG files are accepted.');$ext=match($mime){'application/pdf'=>'pdf','image/jpeg'=>'jpg','image/png'=>'png',default=>'bin'};$stored=bin2hex(random_bytes(16)).'.'.$ext;$dest=$storage.'/'.$stored;if(!move_uploaded_file($f['tmp_name'],$dest))throw new RuntimeException('Unable to store document.');$relative='uploads/documents/'.$stored;$st=$pdo->prepare('INSERT INTO documents(client_id,document_type,original_name,stored_name,file_path,mime_type,file_size,status,uploaded_by) VALUES(?,?,?,?,?,?,?,"uploaded",?)');$st->execute([$client,post_string('document_type','general'),substr((string)$f['name'],0,255),$stored,$relative,$mime,(int)$f['size'],current_user()['id']]);$id=(int)$pdo->lastInsertId();activity($pdo,'upload','documents',$id,'Document uploaded: '.$f['name']);notify_user($pdo,current_user()['id'],$client,'document','Document received','A document has been uploaded to the CRM.');flash('success','Document uploaded safely.');}catch(Throwable $e){error_log('[SPS DOCUMENTS] '.$e->getMessage());$error=$e->getMessage();}}else{$error='Select a client and a valid file.';}}
$clients=$pdo->query("SELECT id,first_name,last_name FROM clients WHERE deleted_at IS NULL ORDER BY last_name")->fetchAll();
$rows=$pdo->query("SELECT d.*,CONCAT(c.first_name,' ',c.last_name) client_name FROM documents d JOIN clients c ON c.id=d.client_id ORDER BY d.id DESC LIMIT 200")->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Documents · SPS CRM</title><style>body{margin:0;background:#f5f7fb;font-family:Arial;color:#172033}.top{background:#fff;border-bottom:1px solid #e5eaf2;padding:18px 28px;display:flex;justify-content:space-between}.top a{color:#315ee7;text-decoration:none}.wrap{max-width:1100px;margin:auto;padding:28px}.grid{display:grid;grid-template-columns:1fr 1.6fr;gap:16px}.card{background:#fff;border:1px solid #e5eaf2;border-radius:15px;padding:20px}.field{margin:10px 0}.field label{display:block;font-size:12px;font-weight:bold;margin-bottom:6px}.field input,.field select{width:100%;padding:10px;border:1px solid #d8dfeb;border-radius:8px}.btn{background:#315ee7;color:#fff;border:0;padding:11px 14px;border-radius:8px;font-weight:bold}.table{width:100%;border-collapse:collapse}.table th,.table td{padding:11px;border-bottom:1px solid #edf0f5;text-align:left;font-size:13px}.success{background:#ebf9f1;color:#176a3c;padding:10px;border-radius:8px;margin-bottom:14px}.error{background:#fff0f0;color:#a32c2c;padding:10px;border-radius:8px;margin-bottom:14px}@media(max-width:800px){.grid{grid-template-columns:1fr}}</style></head><body><header class="top"><strong>SPS CRM · Documents</strong><a href="dashboard.php">← Dashboard</a></header><main class="wrap"><?php if($msg):?><div class="success"><?=e($msg)?></div><?php endif;?><?php if($error):?><div class="error"><?=e($error)?></div><?php endif;?><div class="grid"><div class="card"><h2>Upload Document</h2><form method="post" enctype="multipart/form-data"><?=csrf_field()?><div class="field"><label>Client</label><select name="client_id" required><option value="">Select client</option><?php foreach($clients as $c):?><option value="<?=$c['id']?>"><?=e($c['first_name'].' '.$c['last_name'])?></option><?php endforeach;?></select></div><div class="field"><label>Document Type</label><input name="document_type" value="general"></div><div class="field"><label>File</label><input type="file" name="document" accept=".pdf,.jpg,.jpeg,.png" required></div><button class="btn">Upload</button></form></div><div class="card"><h2>Recent Documents</h2><table class="table"><tr><th>Date</th><th>Client</th><th>Type</th><th>Name</th><th>Status</th><th>Size</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['client_name'])?></td><td><?=e($r['document_type'])?></td><td><?=e($r['original_name'])?></td><td><?=e($r['status'])?></td><td><?=number_format($r['file_size']/1024,1)?> KB</td></tr><?php endforeach;?></table><?php if(!$rows):?><p>No documents yet.</p><?php endif;?></div></div></main></body></html>
